INNER JOIN divisiones_administrativas m ON m.id = c.id_padre AND m.nivel = 2
WHERE c.nivel = 3 AND c.nombre = 'Ampliación Guadalupe Proletaria' AND c.activo = 1
  AND (m.nombre LIKE '%Gustavo A. Madero%' OR m.nombre LIKE '%Gustavo A Madero%')
  AND NOT EXISTS (
    SELECT 1 FROM divisiones_administrativas k
    WHERE k.id_padre = c.id AND k.nivel = 4 AND k.nombre = 'Calle Bosque de Tláhuac' AND k.activo = 1
  )
LIMIT 1;
