SELECT c.id_pais, c.id_tipo, c.id, 'Av. José Loreto Fabela', NULL, NULL, 4, 1, NOW()
FROM divisiones_administrativas c
INNER JOIN divisiones_administrativas m ON m.id = c.id_padre AND m.nivel = 2
WHERE c.nivel = 3 AND c.nombre = 'Zona Escolar Oriente' AND c.activo = 1
  AND (m.nombre LIKE '%Gustavo A. Madero%' OR m.nombre LIKE '%Gustavo A Madero%')
  AND NOT EXISTS (
    SELECT 1 FROM divisiones_administrativas k
    WHERE k.id_padre = c.id AND k.nivel = 4 AND k.nombre = 'Av. José Loreto Fabela' AND k.activo = 1
  )
LIMIT 1;
